// @name JSX: Gallery
// @background #000000
// @refresh 3600
// Photos from the FrameOS Gallery (gallery.frameos.net), full screen: swipe
// left (or tap the right half) for the next one, swipe right (or tap the left
// half) for the one before, and a category at the bottom for another gallery.
// A swipe in from the screen's edge is the frame's scene switch, not this.
//
// The photo on screen is kept (fetchImage's `keep`), decoded once at the
// panel's size: a tap that only changes the caption, a hover or the scene's
// interval draws it again without a download. The gallery hands out a random
// photo per request, so "back" is the one photo kept before this one; past
// it there is nothing to go back to. Each kept photo is the interpreter's: an
// ESP32 short of memory lets the interpreter go and the photos with it, and
// the next render fetches again.
const W = 480, H = 480
const KEPT = 2 // the photo on screen and the one before it
const CATEGORIES = [
  ['cute', 'Cute'],
  ['space-gallery', 'Space'],
  ['masterpieces', 'Buildings'],
  ['low-poly-animals', 'Low poly'],
]

// What lasts the interpreter: the kept photos, newest last, and where we are.
let shown = [] // [{ ref, category, n }]
let at = -1    // index into shown
let want = 0   // +1: a new photo on the next render
let failed = ''

// What lasts the scene: the category and how many photos it has fetched.
let S = null
const load = () => {
  if (S === null) S = Object.assign({ category: 'cute', count: 0 }, frameos.recall('gallery') ?? {})
}
const save = () => frameos.remember('gallery', S)

// `fixed` (the `url` field) is one photo every time, for a snapshot; empty, the gallery.
const fetchNext = (fixed) => {
  const url = fixed || `https://gallery.frameos.net/image?category=${encodeURIComponent(S.category)}` +
    `&width=${W}&height=${H}&fit=cover&format=jpg`
  const photo = frameos.fetchImage(url, { keep: true, width: W, height: H })
  if (!photo.image) {
    failed = photo.error ?? 'the gallery sent nothing'
    return
  }
  failed = ''
  S.count += 1
  save()
  // Past the end of what is kept: the oldest goes.
  shown = shown.slice(0, at + 1)
  shown.push({ ref: photo.image, category: S.category, n: S.count })
  while (shown.length > KEPT) frameos.releaseImage(shown.shift().ref)
  at = shown.length - 1
}

// +1 the next photo (a new one, or the one we came back from), -1 the one before.
const go = (step) => {
  if (step < 0 && at > 0) at -= 1
  else if (step > 0 && at < shown.length - 1) at += 1
  else if (step > 0) want = 1
}

const pick = (category) => {
  if (category === S.category) return
  S.category = category
  save()
  want = 1
}

export function get(app) {
  load()
  if (want > 0 || shown.length === 0) {
    want = 0
    fetchNext(app.config.url)
  }
  const photo = shown[at]
  const label = CATEGORIES.find(([id]) => id === (photo?.category ?? S.category))?.[1] ?? S.category
  return (
    <div className="w-full h-full bg-black text-white"
      onSwipe={(e) => go(e.direction === 'left' ? 1 : e.direction === 'right' ? -1 : 0)}>
      {photo ? <img className="absolute inset-0 w-full h-full object-cover" src={photo.ref} /> : null}
      <div className="absolute inset-y-0 left-0 w-[240px]" onClick={() => go(-1)} />
      <div className="absolute inset-y-0 right-0 w-[240px]" onClick={() => go(1)} />
      <div className="absolute top-3 left-3 right-3 flex items-center justify-between">
        <span className="rounded-full bg-black/60 px-3 py-1 text-sm font-semibold">{label}</span>
        <span className="rounded-full bg-black/60 px-3 py-1 text-sm">
          {photo ? `Photo ${photo.n}${at < shown.length - 1 ? ' (back)' : ''}` : 'No photo'}
        </span>
      </div>
      {failed ? (
        <div className="absolute inset-x-6 top-[200px] rounded-xl bg-red-900/80 p-3">
          <span className="text-sm">{`Could not load a photo: ${failed}`}</span>
        </div>
      ) : null}
      <div className="absolute bottom-3 left-3 right-3 flex gap-2">
        {CATEGORIES.map(([id, name]) => (
          <div className={`flex-1 flex items-center justify-center h-10 rounded-full ${id === S.category ? 'bg-white text-black' : 'bg-black/60 text-white active:bg-white/30'}`}
            onClick={() => pick(id)}>
            <span className="text-sm font-semibold">{name}</span>
          </div>
        ))}
      </div>
    </div>
  )
}
